SELECT ?z ?lbl ?lblType ?ts WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  ?lbl brick:hasLabel ?lblType .
  FILTER(?lbl IN ("DataCenter_bot_ZN_6","Perimeter_top_ZN_3")) .
  OPTIONAL { ?z ref:hasTimeseriesId ?ts }
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl,"ZN_6") || CONTAINS(?lbl,"ZN_3"))
} LIMIT 50

